import { gettext } from "./utils/i18n.js";

document.addEventListener('DOMContentLoaded', function() {
  var csrfToken = window.__ld_csrf_token || '';
  var credentialList = document.getElementById('credential-list');
  var allDomains = [];
  var allCredentials = [];
  var needsMap = {};

  function escapeHtml(s) {
    return s ? String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;') : '';
  }

  function load() {
    fetch(window.__ld_urls?.site_adapters_api || '/settings/site-adapters/api').then(function(r) { return r.json(); }).then(function(d) {
      allDomains = d.domains || [];
      allCredentials = d.credentials || [];
      needsMap = {};
      allDomains.forEach(function(d) { needsMap[d.domain] = d; });
      render();
    });
  }

  function statusBadge(status) {
    switch (status) {
      case 'valid': return '<span class="wa-badge wa-badge-ok">valid &#10003;</span>';
      case 'expired': return '<span class="wa-badge wa-badge-warn">expired &#10005;</span>';
      case 'key_changed': return '<span class="wa-badge wa-badge-warn">key changed &#9888;</span>';
      case 'missing': return '<span class="wa-badge wa-badge-warn">missing &#10005;</span>';
      default: return '';
    }
  }

  function getAvailableTypes(domain) {
    var need = needsMap[domain];
    if (!need) return [];
    var types = [];
    if (need.needs_cookie) types.push('cookie');
    if (need.needs_headers && need.needs_headers.length) types.push('header');
    if (need.needs_token) types.push('token');
    return types;
  }

  function render() {
    if (allCredentials.length === 0) {
      credentialList.innerHTML = '<p class="text-gray">' + gettext('No credentials added yet.') + '</p>';
      return;
    }
    var html = '';
    allCredentials.forEach(function(c) {
      var updated = c.updated_at ? c.updated_at.split('T')[0] : '';
      var typeLabel = c.type === 'cookie' ? 'Cookie' : (c.type === 'token' ? 'Token' : 'Header');
      var detail = '';
      if (c.type === 'header' && c.header_names && c.header_names.length) {
        detail = ' <span class="text-gray" style="font-size:12px">(' + escapeHtml(c.header_names.join(', ')) + ')</span>';
      }

      html += '<div class="wa-cookie-row">'
        + '<div class="wa-cookie-header">'
        + '<div style="flex:1;display:flex;align-items:center;gap:8px;flex-wrap:wrap">'
        + '<strong>' + escapeHtml(c.domain) + '</strong>'
        + ' <span class="wa-badge">' + escapeHtml(typeLabel) + '</span>'
        + detail
        + ' ' + statusBadge(c.status)
        + (updated ? ' <span class="text-gray" style="font-size:12px">' + escapeHtml(updated) + '</span>' : '')
        + '</div>'
        + '<div style="display:flex;gap:4px">'
        + '<button class="btn btn-sm js-edit-cred" data-domain="' + escapeHtml(c.domain) + '" data-type="' + escapeHtml(c.type) + '">Edit</button>'
        + '<button class="btn btn-sm btn-error js-delete-cred" data-domain="' + escapeHtml(c.domain) + '" data-type="' + escapeHtml(c.type) + '">Delete</button>'
        + '</div>'
        + '</div></div>';
    });
    credentialList.innerHTML = html;
  }

  function showModal(title, domain, type) {
    var host = document.querySelector('.modals');
    var existing = null;
    if (domain) {
      existing = allCredentials.find(function(c) { return c.domain === domain && c.type === type; }) || null;
    }

    var availableTypes = domain ? getAvailableTypes(domain) : [];
    var selectedType = type || (availableTypes.length ? availableTypes[0] : 'cookie');
    var showTypeSelector = availableTypes.length > 1;

    var modal = document.createElement('div');
    modal.className = 'modal active wa-dialog';
    var html = '<div class="modal-overlay"></div>'
      + '<div class="modal-container" style="max-width:90vw;width:600px">'
      + '<div class="modal-header"><h2>' + escapeHtml(title) + '</h2><button class="btn btn-clear" aria-label="Close"></button></div>'
      + '<div class="modal-body">';

    if (domain) {
      html += '<p style="margin-bottom:12px"><strong>' + escapeHtml(domain) + '</strong></p>';
    } else {
      html += '<div class="form-group"><label class="form-label">Domain</label>'
        + '<div style="position:relative"><input type="text" class="form-input" id="dlg-domain" placeholder="example.com" autocomplete="off">'
        + '<div id="dlg-domain-dropdown" class="wa-url-dropdown"></div></div></div>';
    }

    // Type selector
    if (showTypeSelector) {
      html += '<div class="form-group"><label class="form-label">Type</label>'
        + '<div style="display:flex;gap:12px">';
      availableTypes.forEach(function(t) {
        var label = t === 'cookie' ? 'Cookie' : (t === 'token' ? 'Token' : 'Header');
        var checked = t === selectedType ? 'checked' : '';
        html += '<label><input type="radio" name="dlg-type" value="' + t + '" ' + checked + '> ' + label + '</label>';
      });
      html += '</div></div>';
    } else if (availableTypes.length === 1) {
      html += '<input type="hidden" name="dlg-type" value="' + availableTypes[0] + '">';
    } else {
      html += '<div class="form-group"><label class="form-label">Type</label>'
        + '<div style="display:flex;gap:12px">'
        + '<label><input type="radio" name="dlg-type" value="cookie" ' + (selectedType === 'cookie' ? 'checked' : '') + '> Cookie</label>'
        + '<label><input type="radio" name="dlg-type" value="header" ' + (selectedType === 'header' ? 'checked' : '') + '> Header</label>'
        + '<label><input type="radio" name="dlg-type" value="token" ' + (selectedType === 'token' ? 'checked' : '') + '> Token</label>'
        + '</div></div>';
    }

    // Cookie fields
    html += '<div id="dlg-cookie-fields" style="display:' + (selectedType === 'cookie' ? 'block' : 'none') + '">'
      + '<div class="form-group"><label class="form-label">Cookie</label>'
      + '<textarea class="form-input" id="dlg-cookie-value" rows="3" placeholder="name1=value1; name2=value2">'
      + escapeHtml(existing && existing.type === 'cookie' ? (existing.cookie || '') : '')
      + '</textarea></div></div>';

    // Header fields
    html += '<div id="dlg-header-fields" style="display:' + (selectedType === 'header' ? 'block' : 'none') + '">'
      + '<div id="dlg-header-rows"></div>'
      + '<button class="btn btn-sm" id="btn-add-header-row" style="margin-top:8px">+ Add header</button>'
      + '</div>';

    // Token fields
    html += '<div id="dlg-token-fields" style="display:' + (selectedType === 'token' ? 'block' : 'none') + '">'
      + '<div class="form-group"><label class="form-label">Refresh Token</label>'
      + '<textarea class="form-input" id="dlg-token-value" rows="2" placeholder="Paste your refresh_token here">'
      + escapeHtml(existing && existing.type === 'token' ? (existing.token || '') : '')
      + '</textarea></div></div>';

    html += '</div>'
      + '<div class="modal-footer"><button class="btn" id="dlg-cancel">Cancel</button><button class="btn btn-primary" id="dlg-save">Save</button></div>'
      + '</div>';

    modal.innerHTML = html;

    // Build header rows
    function buildHeaderRows(domainKey) {
      var container = modal.querySelector('#dlg-header-rows');
      var need = needsMap[domainKey] || {};
      var declaredHeaders = need.needs_headers || [];

      // Collect existing values
      var existingValues = {};
      if (existing && existing.type === 'header') {
        // existing doesn't have the raw values, we need to get them from the API
        // For now, just use empty values
      }

      container.innerHTML = '';

      // Show declared headers first
      declaredHeaders.forEach(function(name) {
        addHeaderRow(container, name, '', true);
      });

      // Show custom headers button hint
      if (declaredHeaders.length > 0) {
        var hint = document.createElement('div');
        hint.className = 'form-input-hint';
        hint.style.marginTop = '4px';
        hint.textContent = 'Additional headers:';
        container.appendChild(hint);
      }
    }

    function addHeaderRow(container, name, value, isDeclared) {
      var row = document.createElement('div');
      row.style.cssText = 'display:flex;gap:8px;align-items:center;margin-bottom:8px';

      var nameEl;
      if (isDeclared) {
        nameEl = document.createElement('span');
        nameEl.style.cssText = 'white-space:nowrap;font-family:monospace;font-size:13px';
        nameEl.textContent = name;
      } else {
        nameEl = document.createElement('input');
        nameEl.type = 'text';
        nameEl.className = 'form-input';
        nameEl.style.width = '180px';
        nameEl.placeholder = 'Header-Name';
        nameEl.value = name;
      }

      var valueInput = document.createElement('input');
      valueInput.type = 'text';
      valueInput.className = 'form-input';
      valueInput.style.flex = '1';
      valueInput.style.minWidth = '0';
      valueInput.placeholder = 'value';
      valueInput.value = value;
      valueInput.dataset.headerName = name;
      valueInput.dataset.isDeclared = isDeclared ? '1' : '0';

      row.appendChild(nameEl);
      row.appendChild(valueInput);

      if (!isDeclared) {
        var removeBtn = document.createElement('button');
        removeBtn.className = 'btn btn-sm btn-error';
        removeBtn.textContent = '\u00d7';
        removeBtn.style.whiteSpace = 'nowrap';
        removeBtn.addEventListener('click', function() { row.remove(); });
        row.appendChild(removeBtn);
      }

      container.appendChild(row);
    }

    // Initialize header rows
    if (domain) {
      buildHeaderRows(domain);
    }

    // Add custom header button
    modal.querySelector('#btn-add-header-row').addEventListener('click', function() {
      var container = modal.querySelector('#dlg-header-rows');
      addHeaderRow(container, '', '', false);
    });

    // Toggle fields based on type
    modal.querySelectorAll('input[name="dlg-type"]').forEach(function(radio) {
      radio.addEventListener('change', function() {
        modal.querySelector('#dlg-cookie-fields').style.display = this.value === 'cookie' ? 'block' : 'none';
        modal.querySelector('#dlg-header-fields').style.display = this.value === 'header' ? 'block' : 'none';
        var tokenFields = modal.querySelector('#dlg-token-fields');
        if (tokenFields) tokenFields.style.display = this.value === 'token' ? 'block' : 'none';
      });
    });

    // Setup domain dropdown
    if (!domain) {
      var domainInput = modal.querySelector('#dlg-domain');
      var dropdown = modal.querySelector('#dlg-domain-dropdown');

      function updateAvailableTypes(d) {
        var types = getAvailableTypes(d);
        var cookieFields = modal.querySelector('#dlg-cookie-fields');
        var headerFields = modal.querySelector('#dlg-header-fields');

        if (types.length === 0) {
          modal.querySelectorAll('input[name="dlg-type"]').forEach(function(r) {
            r.closest('label').style.display = '';
          });
          return;
        }

        modal.querySelectorAll('input[name="dlg-type"]').forEach(function(r) {
          var label = r.closest('label');
          label.style.display = types.indexOf(r.value) >= 0 ? '' : 'none';
        });

        var firstRadio = modal.querySelector('input[name="dlg-type"][value="' + types[0] + '"]');
        if (firstRadio) {
          firstRadio.checked = true;
          if (cookieFields) cookieFields.style.display = types[0] === 'cookie' ? 'block' : 'none';
          if (headerFields) headerFields.style.display = types[0] === 'header' ? 'block' : 'none';
        }

        // Rebuild header rows for new domain
        buildHeaderRows(d);
      }

      function showDropdown() {
        var query = domainInput.value.toLowerCase();
        var filtered = allDomains.filter(function(d) {
          return d.domain.toLowerCase().indexOf(query) >= 0;
        });

        dropdown.innerHTML = '';
        if (filtered.length === 0 && !query) {
          dropdown.classList.remove('open');
          return;
        }

        filtered.forEach(function(d) {
          var item = document.createElement('div');
          item.className = 'wa-url-dropdown-item';
          var types = getAvailableTypes(d.domain);
          var typeLabels = types.map(function(t) { return t === 'cookie' ? 'Cookie' : (t === 'token' ? 'Token' : 'Header'); });
          var hintStr = typeLabels.length ? ' <span class="text-gray" style="font-size:12px">(' + escapeHtml(typeLabels.join(' + ')) + ')</span>' : '';
          item.innerHTML = '<span>' + escapeHtml(d.domain) + hintStr + '</span>';
          item.addEventListener('mousedown', function(e) {
            e.preventDefault();
            domainInput.value = d.domain;
            dropdown.classList.remove('open');
            updateAvailableTypes(d.domain);
          });
          dropdown.appendChild(item);
        });

        dropdown.classList.add('open');
      }

      domainInput.addEventListener('input', showDropdown);
      domainInput.addEventListener('focus', showDropdown);
      domainInput.addEventListener('blur', function() {
        setTimeout(function() { dropdown.classList.remove('open'); }, 200);
      });
    }

    function close() { modal.remove(); }

    modal.querySelector('.modal-overlay').addEventListener('click', close);
    modal.querySelector('.btn-clear').addEventListener('click', close);
    modal.querySelector('#dlg-cancel').addEventListener('click', close);

    modal.querySelector('#dlg-save').addEventListener('click', function() {
      var d = domain || (modal.querySelector('#dlg-domain') ? modal.querySelector('#dlg-domain').value.trim() : '');
      if (!d) { alert('Please enter a domain'); return; }

      var typeRadio = modal.querySelector('input[name="dlg-type"]:checked');
      var credType = typeRadio ? typeRadio.value : 'cookie';

      if (credType === 'cookie') {
        var cookieVal = modal.querySelector('#dlg-cookie-value').value.trim();
        if (!cookieVal) { alert('Please enter cookie value'); return; }
        saveApi(d, 'cookie', cookieVal, '').then(function() { close(); load(); });
      } else if (credType === 'token') {
        var tokenVal = modal.querySelector('#dlg-token-value').value.trim();
        if (!tokenVal) { alert('Please enter refresh token'); return; }
        saveApi(d, 'token', tokenVal, '').then(function() { close(); load(); });
      } else {
        // Collect all header rows
        var rows = modal.querySelectorAll('#dlg-header-rows input[type="text"]');
        var headers = {};
        var hasError = false;

        rows.forEach(function(input) {
          var headerName = input.dataset.headerName || '';
          var headerValue = input.value.trim();

          // For custom headers, get the name from the sibling input
          if (!input.dataset.isDeclared || input.dataset.isDeclared === '0') {
            // Find the name input in the same row
            var row = input.closest('div[style]');
            var nameInput = row.querySelector('input[type="text"]:first-child');
            if (nameInput) headerName = nameInput.value.trim();
          }

          if (headerName && headerValue) {
            headers[headerName] = headerValue;
          }
        });

        if (Object.keys(headers).length === 0) {
          alert('Please enter at least one header value');
          return;
        }

        // Save all headers
        var promises = Object.keys(headers).map(function(name) {
          return saveApi(d, 'header', headers[name], name);
        });
        Promise.all(promises).then(function() { close(); load(); });
      }
    });

    host.appendChild(modal);
    setTimeout(function() {
      var first = modal.querySelector('input[type="text"], textarea');
      if (first) first.focus();
    }, 0);
  }

  function saveApi(domain, type, value, headerName) {
    var fd = new FormData();
    fd.append('action', 'save');
    fd.append('domain', domain);
    fd.append('type', type);
    fd.append('value', value);
    if (headerName) fd.append('header_name', headerName);
    return fetch(window.__ld_urls?.site_adapters_api || '/settings/site-adapters/api', { method: 'POST', headers: {'X-CSRFToken': csrfToken}, body: fd })
      .then(function(r) { return r.json(); });
  }

  credentialList.addEventListener('click', function(e) {
    var btn = e.target.closest('.js-edit-cred, .js-delete-cred');
    if (!btn) return;
    var domain = btn.dataset.domain;
    var type = btn.dataset.type;
    if (btn.classList.contains('js-edit-cred')) {
      showModal('Edit: ' + domain, domain, type);
    } else {
      if (!confirm('Delete ' + type + ' credentials for ' + domain + '?')) return;
      var fd = new FormData();
      fd.append('action', 'delete');
      fd.append('domain', domain);
      fd.append('type', type);
      fetch(window.__ld_urls?.site_adapters_api || '/settings/site-adapters/api', { method: 'POST', headers: {'X-CSRFToken': csrfToken}, body: fd })
        .then(function(r) { return r.json(); })
        .then(function() { load(); });
    }
  });

  document.getElementById('btn-add-credential').addEventListener('click', function() {
    showModal('Add credentials', null, null);
  });

  // Check URL params (from bookmarklet)
  var params = new URLSearchParams(window.location.search);
  if (params.get('domain')) {
    var domain = params.get('domain');
    var cookie = params.get('cookie') || '';
    if (domain && cookie) {
      saveApi(domain, 'cookie', cookie, '').then(function() { load(); });
    }
    window.history.replaceState({}, '', '/settings/site-adapters');
  }

  load();
});

// ============ Snapshot Toggles ============
(function() {
  var togglesUrl = window.__ld_toggles_url || '/settings/toggles';
  var csrf = window.__ld_csrf_token || csrfToken;
  var toggleList = document.getElementById('toggle-prefs-list');
  var toggleEmpty = document.getElementById('toggle-prefs-empty');
  if (!toggleList) return;

  function loadToggles() {
    fetch(togglesUrl).then(function(r) { return r.json(); }).then(function(data) {
      var domains = data.domains || [];
      var prefs = data.preferences || {};
      if (domains.length === 0) {
        toggleList.innerHTML = '';
        if (toggleEmpty) { toggleEmpty.textContent = gettext('No customizable sites available yet.'); toggleEmpty.style.display = ''; }
        return;
      }
      if (toggleEmpty) toggleEmpty.style.display = 'none';
      var html = '';
      for (var i = 0; i < domains.length; i++) {
        var d = domains[i];
        var domain = d.domain;
        var toggles = d.toggles || {};
        var userDomainPrefs = prefs[domain] || {};
        html += '<div class="wa-cookie-row"><div class="wa-cookie-header"><strong>' + escapeHtml(domain) + '</strong></div>';
        for (var tid in toggles) {
          if (!Object.prototype.hasOwnProperty.call(toggles, tid)) continue;
          var t = toggles[tid];
          var label = t.label || tid;
          var defaultRemove = !!t.default;
          var userChoice = userDomainPrefs[tid];
          var isChecked = (userChoice !== undefined) ? userChoice : defaultRemove;
          html += '<label class="form-switch" style="margin:4px 0 4px 16px">'
            + '<input type="checkbox" class="wa-toggle-pref" data-domain="' + escapeHtml(domain) + '" data-toggle="' + escapeHtml(tid) + '"' + (isChecked ? ' checked' : '') + '>'
            + '<i class="form-icon"></i> ' + escapeHtml(label)
            + '</label>';
        }
        html += '</div>';
      }
      toggleList.innerHTML = html;
    });
  }

  toggleList.addEventListener('change', function(e) {
    var cb = e.target.closest('.wa-toggle-pref');
    if (!cb) return;
    var fd = new FormData();
    fd.append('domain', cb.dataset.domain);
    fd.append('toggle_id', cb.dataset.toggle);
    fd.append('enabled', String(cb.checked));
    fetch(togglesUrl, { method: 'POST', headers: {'X-CSRFToken': csrf}, body: fd })
      .then(function(r) { return r.json(); })
      .then(function(data) {
        if (data.error) { alert(data.error); cb.checked = !cb.checked; }
      })
      .catch(function() { cb.checked = !cb.checked; });
  });

  loadToggles();
})();
